torch._dynamo.mark_dynamic(x, 0)

def f(x):
    pred = x.shape[0] == 1
    return torch.cond(pred, true_true_fn, true_false_fn, [x])
torch.compile(torch.func.functionalize(f), backend="eager")(x)
